'use strict';

const fs = require('fs');
const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/);
const output = [];

function mul(a, b, mod) {
    const c = Array.from({ length: a.length }, () =>
        Array(b[0].length).fill(0n)
    );

    for (let i = 0; i < a.length; i++) {
        for (let k = 0; k < a[0].length; k++) {
            for (let j = 0; j < b[0].length; j++) {
                c[i][j] = (c[i][j] + a[i][k] * b[k][j] % mod) % mod;
            }
        }
    }
    return c;
}

function qPow(base, exponent, mod) {
    let ans = Array.from({ length: base.length }, () =>
        Array(base.length).fill(0n)
    );

    for (let i = 0; i < ans.length; i++) {
        ans[i][i] = 1n;
    }

    while (exponent !== 0n) {
        if (exponent & 1n) {
            ans = mul(ans, base, mod);
        }
        base = mul(base, base, mod);
        exponent >>= 1n;
    }

    return ans;
}

for (let p = 0; p + 5 < input.length; p += 6) {
    const n = BigInt(input[p]);
    let sx = BigInt(input[p + 1]);
    let sy = BigInt(input[p + 2]);
    const dx = BigInt(input[p + 3]);
    const dy = BigInt(input[p + 4]);
    const t = BigInt(input[p + 5]);

    sx--;
    sy--;

    let a = [
        [2n, 1n, 1n, 0n, 1n, 2n],
        [1n, 2n, 0n, 1n, 1n, 2n],
        [1n, 1n, 1n, 0n, 1n, 2n],
        [1n, 1n, 0n, 1n, 1n, 2n],
        [0n, 0n, 0n, 0n, 1n, 1n],
        [0n, 0n, 0n, 0n, 0n, 1n]
    ];

    a = qPow(a, t, n);

    const b = [
        [sx],
        [sy],
        [((dx % n) + n) % n],
        [((dy % n) + n) % n],
        [0n],
        [1n]
    ];

    a = mul(a, b, n);
    output.push(`${a[0][0] + 1n} ${a[1][0] + 1n}`);
}

process.stdout.write(output.join('\n'));

